import{_ as r,C as a,o as l,c as d,a2 as o,E as n}from"./chunks/framework.BME6yAZ4.js";const b=JSON.parse('{"title":"把需求和流程交代清楚","description":"用准确的动作、对象、字段、顺序和条件，把口语化要求改写成智能体可以执行的工作流程。","frontmatter":{"title":"把需求和流程交代清楚","description":"用准确的动作、对象、字段、顺序和条件，把口语化要求改写成智能体可以执行的工作流程。","prev":{"text":"提供高质量的上下文","link":"/30min/context"},"next":{"text":"明确交付要求与质量标准","link":"/30min/output"}},"headers":[],"relativePath":"30min/workflow.md","filePath":"30min/workflow.md","lastUpdated":1786896277000}'),i={name:"30min/workflow.md"};function s(c,t,p,h,u,_){const e=a("TaskBriefBuilder");return l(),d("div",null,[t[0]||(t[0]=o('<h1 id="把需求和流程交代清楚" tabindex="-1">把需求和流程交代清楚 <a class="header-anchor" href="#把需求和流程交代清楚" aria-label="Permalink to &quot;把需求和流程交代清楚&quot;">​</a></h1><p>这一部分只解决一个问题：<strong>怎样把自己脑中的做法，准确地说成智能体可以执行的流程。</strong></p><p>“帮我整理一下”“把后续安排好”这类说法，人类同事可能会结合经验猜出你的意思，智能体却容易漏步骤、用错资料或做出与你预期不同的动作。关键不是把话写得更长，而是使用含义明确的操作表达，把每一步说清楚。</p><h2 id="把任务变成可执行的流程" tabindex="-1">把任务变成可执行的流程 <a class="header-anchor" href="#把任务变成可执行的流程" aria-label="Permalink to &quot;把任务变成可执行的流程&quot;">​</a></h2><p>要让智能体做对事，先像交代一位同事一样，把目标、对象、动作和完成方式讲明白。下面三步合在一起，就是一条可执行的任务描述。</p><h3 id="用准确动词描述动作" tabindex="-1">用准确动词描述动作 <a class="header-anchor" href="#用准确动词描述动作" aria-label="Permalink to &quot;用准确动词描述动作&quot;">​</a></h3><p>准确表达不是堆砌黑话，而是选用能够对应具体操作的动词：</p><table tabindex="0"><thead><tr><th>想表达什么</th><th>推荐使用的动词</th><th>说明</th></tr></thead><tbody><tr><td>找到信息</td><td>读取、检索、筛选</td><td>说明从哪里取得哪些资料</td></tr><tr><td>整理信息</td><td>提取、分类、去重、汇总</td><td>说明怎样处理原始内容</td></tr><tr><td>检查信息</td><td>核对、比对、验证</td><td>说明依据什么检查</td></tr><tr><td>形成结果</td><td>生成、写入、创建、发送</td><td>说明产生什么或改变什么</td></tr><tr><td>交回结果</td><td>返回、列出、标记</td><td>说明智能体完成后要提供什么证据</td></tr></tbody></table><p>例如，不说“看看会议里都说了什么”，而说“<strong>读取本次会议纪要，提取行动项</strong>”。不说“把时间弄一下”，而说“<strong>查询团队日历，比对行动项是否存在时间冲突</strong>”。</p><h3 id="为动作补齐对象和字段" tabindex="-1">为动作补齐对象和字段 <a class="header-anchor" href="#为动作补齐对象和字段" aria-label="Permalink to &quot;为动作补齐对象和字段&quot;">​</a></h3><p>只有动词还不够。每一步最好说清楚三个部分：</p><blockquote><p><strong>动作 + 操作对象 + 需要处理的字段或规则</strong></p></blockquote><p>例如：</p><ul><li><code>读取</code> + <code>本次会议纪要与工作群最新消息</code></li><li><code>提取</code> + <code>行动项</code> + <code>事项、负责人、截止时间和出处</code></li><li><code>比对</code> + <code>行动项与团队日历</code> + <code>检查时间冲突</code></li><li><code>创建</code> + <code>任务与日程</code> + <code>使用确认后的负责人和时间</code></li></ul><p>这样，智能体不仅知道“要整理会议”，还知道从哪里读取、要提取什么，以及下一步操作哪些对象。</p><h3 id="用顺序和条件串成流程" tabindex="-1">用顺序和条件串成流程 <a class="header-anchor" href="#用顺序和条件串成流程" aria-label="Permalink to &quot;用顺序和条件串成流程&quot;">​</a></h3><p>最后，用流程词把各个动作连接起来：</p><ul><li><strong>先、再、随后、最后</strong>：说明执行顺序。</li><li><strong>若……则……，否则……</strong>：说明分支条件。</li><li><strong>确认后、通过后</strong>：说明什么时候可以继续执行。</li><li><strong>直到……为止</strong>：说明流程的结束条件。</li></ul><p>例如，把“把工作讨论会后续安排好”改写为：</p><blockquote><p>先读取本次会议纪要和工作群最新消息，提取行动项的事项、负责人、截止时间和出处；再查询团队日历，比对是否存在时间冲突。若负责人或截止时间缺失，则标记为待确认，不自行补写；信息完整后生成任务、日程和通知草稿，待我确认后创建并发送，最后返回任务链接、日程状态和消息发送结果。</p></blockquote>',20)),n(e),t[1]||(t[1]=o('<blockquote><p>判断流程有没有说清楚，可以逐步问：<strong>做什么动作？操作什么对象？处理哪些字段？先后顺序是什么？遇到不同情况怎么办？完成后返回什么？</strong></p></blockquote><h2 id="多用行业术语与业务口径" tabindex="-1">多用行业术语与业务口径 <a class="header-anchor" href="#多用行业术语与业务口径" aria-label="Permalink to &quot;多用行业术语与业务口径&quot;">​</a></h2><p>清楚的执行流程是基础。如果希望智能体的判断和表达更贴近真实业务，还要补充当前行业的专业术语，以及你所在组织采用的具体口径。</p><p>不要只丢给它几个行业词汇，而要同时提供：</p><ul><li><strong>术语名称与定义</strong>：这个词在当前行业中具体指什么。</li><li><strong>企业内部口径</strong>：公司怎样计算、分类或使用这个术语。</li><li><strong>正确示例</strong>：一段符合要求的历史材料或标准结果。</li></ul><p>例如在活动运营场景中，可以说明“报名人数、到场人数、核销人数、到场率”的定义和计算方式，再要求智能体据此整理活动复盘。这样它不会只写“现场参与情况较好”，而能按照统一口径计算并呈现业务数据。</p><blockquote><p>行业术语不能代替清楚的执行流程。先让智能体知道怎样做，再让它按照你的业务口径做得更准确。</p></blockquote><h2 id="通过多轮沟通把流程调顺" tabindex="-1">通过多轮沟通把流程调顺 <a class="header-anchor" href="#通过多轮沟通把流程调顺" aria-label="Permalink to &quot;通过多轮沟通把流程调顺&quot;">​</a></h2><p>不需要在第一句话里把所有细节都说对。把智能体当作协作同事：先交代你已经明确的目标和资料，再根据它给出的结果补充反馈，一起把流程调顺。</p><p>当第一次结果不符合预期时，不必从头重写整段要求。直接指出具体问题，并告诉它下一轮怎样调整：</p><ul><li><strong>遗漏了什么</strong>：例如“漏掉了会议纪要里的负责人和截止时间，请补齐后再生成任务草稿。”</li><li><strong>哪一步不对</strong>：例如“先不要创建日程，先把有时间冲突的事项单独列出来让我确认。”</li><li><strong>结果该怎样改</strong>：例如“把任务按负责人分组，并在每项后保留原始出处。”</li></ul><p>每一次反馈都会成为下一轮对话的上下文。经过几轮“给结果 → 看问题 → 补反馈”，就能把一项模糊的想法逐步收敛成稳定、顺畅的执行流程。</p><blockquote><p>关键不是一次性写出完美指令，而是让每一轮反馈都足够具体，能让下一步比上一步更接近你要的结果。</p></blockquote>',13))])}const k=r(i,[["render",s]]);export{b as __pageData,k as default};
